import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Input,
  OnDestroy,
  Output,
} from '@angular/core';
import { PresentsetupService } from '../../../services/presentsetup/presentsetup.service';
import { presentOngoingList, TypeRes } from '../../../interfaces/presentsetup';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { Router } from '@angular/router';
import { PresentService } from '../../../services/present/present.service';
import { MatMenuModule } from '@angular/material/menu';
import { Subscription } from 'rxjs';
import { SocketService } from '../../../../core/services/socket/socket.service';
import { presentEvents } from '../../../interfaces/present.tool.interface';

@Component({
  selector: 'present-list',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [AvatarComponent, ButtonComponent, MatMenuModule],
  templateUrl: './present-list.component.html',
  styleUrl: './present-list.component.scss',
})
export class PresentListComponent implements OnDestroy {
  ongoingList: presentOngoingList[] = [];

  @Input() presentTypes: TypeRes[] = [];
  @Input() nCaseid: string;
  @Output() changeHandler = new EventEmitter();
  nUserid: string;

  isLoading: boolean = true;

  presentSubscribe: Subscription;

  constructor(
    private readonly PSservice: PresentsetupService,
    private store: SecureStorageService,
    private cdr: ChangeDetectorRef,
    private router: Router,
    private presentSerice: PresentService,
    private socket: SocketService
  ) {
    this.presentSubscribe = this.socket
      .getPresentationTools()
      .subscribe((res: presentEvents) => {
        if (['LIVE', 'USER-MANAGE', 'END'].includes(res?.event)) {
          this.getOngoingList();
          this.changeHandler.emit('refetch');
        }
      });
  }

  async ngOnInit() {
    this.isLoading = true;
    try {
      this.nUserid = await this.store.getUserId();
      await this.getOngoingList();
    } catch (error) {
      console.error(error);
    }
    this.isLoading = false;
    this.cdr.detectChanges();
  }

  goToPresent(nPresentid: string) {
    if (!nPresentid) return;
    // const url = this.router.serializeUrl(
    //   this.router.createUrlTree(['/individual/doc', encodeURIComponent(
    //     JSON.stringify([[], this.nCaseid, nPresentid])
    //   ) ])
    // );
    // this.router.navigateByUrl(url);

    this.router.navigateByUrl(
      `/individual/doc/${encodeURIComponent(
        JSON.stringify([[], this.nCaseid, nPresentid])
      )}`
    );
  }

  async endPresent(nPresentid: string) {
    const res = await this.presentSerice.endPresentation(nPresentid);
    if (res?.length && res[0].msg == 1) {
      const idx = this.ongoingList.findIndex((e) => e.nPresentid == nPresentid);
      if (idx > -1) {
        this.ongoingList.splice(idx, 1);
      }
      this.changeHandler.emit('refetch');
      this.cdr.detectChanges();
    }
  }

  async getOngoingList() {
    this.ongoingList = await this.PSservice.ongoing(this.nCaseid);
    // this.ongoingList = this.ongoingList.filter((e) => !(e.cStatus == 'I' && e.nCreateid != this.nUserid));
    // this.ongoingList = this.ongoingList.filter((e) => e.cStatus != 'I' || e.nCreateid == this.nUserid);
    this.ongoingList = this.ongoingList.filter(e => e.cStatus != 'I');

    this.cdr.detectChanges();
  }

  ngOnDestroy(): void {
    //Add 'implements OnDestroy' to the class.
    this.presentSubscribe.unsubscribe();
  }
}
